# ui.py — АВТО-ГЕНЕРИРУЕМЫЙ ФАЙЛ, не редактируй его вручную.
# Исходники интерфейса: ui_src/{app,main,settings}.css, ui_src/{app,common,settings}.js,
#                       ui_src/{index,settings}.html
# Сборка: python tools/build_ui.py   Проверка: python tools/build_ui.py --check

APP_CSS = '  /* Общие стили: главное окно и окно настроек. Своя вёрстка окон лежит\n     в main.css / settings.css, здесь только база и элементы управления. */\n  * { box-sizing: border-box; }\n  body {\n    margin: 0; padding: 16px;\n    font-family: var(--font-sans, "Segoe UI"), system-ui, sans-serif;\n    background: var(--bg); color: var(--text); font-size: 14px;\n    opacity: var(--opacity);\n  }\n  /* поля и строки прячутся по visible_if из схемы, а .row/.range-row задают\n     display: flex - без этого браузер показал бы скрытые строки */\n  [hidden] { display: none !important; }\n\n  label { display: block; margin: 10px 0 4px; font-size: 13px; opacity: .9; }\n  input[type=text], input[type=password], select {\n    width: 100%; padding: 8px 10px; border-radius: var(--radius-s); border: 1px solid var(--surface);\n    background: var(--widget); color: var(--text); font-size: 14px; outline: none;\n  }\n  input[type=text]:focus, input[type=password]:focus, select:focus { border-color: var(--accent); }\n  input:disabled, select:disabled, button:disabled { opacity: .45; }\n  input[type=number] {\n    box-sizing: border-box; width: 64px; flex: 0 0 64px;\n    padding: 6px 8px; border-radius: var(--radius-s); border: 1px solid var(--surface);\n    background: var(--widget); color: var(--text); font-size: 13px; outline: none; text-align: center;\n  }\n  input[type=number]:focus { border-color: var(--accent); }\n  input[type=range] {\n    flex: 1 1 0; min-width: 0; accent-color: var(--accent); height: 4px;\n  }\n  button {\n    padding: 8px 18px; border: none; border-radius: var(--radius-s); cursor: pointer;\n    background: var(--surface); color: var(--text); font-size: 14px;\n  }\n  button:hover { background: var(--accent); color: var(--bg); }\n  button:disabled:hover { background: var(--surface); color: var(--text); cursor: default; }\n  .icon-btn {\n    width: 36px; height: 36px; padding: 0; font-size: 18px; line-height: 1;\n    display: flex; align-items: center; justify-content: center; flex: none;\n  }\n  .row { display: flex; align-items: center; gap: 8px; }\n  .row input[type=text] { flex: 1; }\n  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; }\n  .check { display: flex; align-items: center; gap: 6px; margin: 10px 0 4px; font-size: 13px; }\n  .check input { width: 15px; height: 15px; accent-color: var(--accent); }\n  .range-row { display: flex; align-items: center; gap: 8px; margin-top: 8px; }\n  .range-row label { display: inline-block; margin: 0; min-width: 0; font-size: 13px; white-space: nowrap; }\n  .range-row input[type=text], .range-row input[type=password], .range-row select { flex: 1 1 0; min-width: 0; }\n  .row input { flex: 1 1 0; min-width: 0; }\n  .note { margin-top: 6px; font-size: 12px; opacity: .7; }\n  #ftp-test-note.ok { color: var(--accent); opacity: 1; }\n  #ftp-test-note.bad { color: var(--warn); opacity: 1; }\n  .settings-box {\n    margin-top: 12px; padding: 10px 12px; border: 1px solid var(--widget);\n    border-radius: var(--radius-m); background: var(--widget);\n  }\n  .settings-box-title {\n    font-size: 11px; font-weight: 600; opacity: .65;\n    text-transform: uppercase; letter-spacing: .4px; margin-bottom: 8px;\n  }\n\n  /* ---- кнопки-действия настроек (темы, шрифты, FTP) ---- */\n  .theme-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }\n  .theme-actions button {\n    /* nowrap + flex:1/min-width:0 обрезали длинные подписи ("Schriften neu laden",\n       "Обновить шрифты") — строка переносится, кнопки перетекают на вторую. */\n    flex: 1 1 auto; min-width: 0; padding: 8px 10px;\n    display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n    font-size: 13px; line-height: 1.15; white-space: normal; overflow-wrap: anywhere;\n    background: transparent; color: var(--text);\n    border: 1px solid var(--widget); border-radius: var(--radius-s);\n    cursor: pointer; transition: border-color .15s, color .15s, background .15s;\n  }\n  .theme-actions button:hover { border-color: var(--accent); color: var(--accent); background: rgba(255,255,255,.05); }\n  .theme-actions button:active { transform: scale(.97); }\n  .theme-actions button.done { border-color: var(--accent); color: var(--accent); }\n  .theme-actions .ta-ico { font-size: 14px; line-height: 1; opacity: .75; }\n  .theme-actions button:hover .ta-ico { opacity: 1; }\n\n  /* ---- модальный оверлей главного окна: пока открыто окно настроек,\n     главное окно не принимает клики ---- */\n  .overlay {\n    position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 50;\n  }\n'

MAIN_CSS = '  /* Стили только главного окна. Общие элементы управления лежат в app.css,\n     вёрстка окна настроек — в settings.css. */\n  h1 { font-size: 22px; margin: 0 0 8px; }\n  .sub { opacity: .65; font-size: 12px; }\n  .head { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 14px; }\n  .brand { flex: 1; min-width: 0; }\n  .logo {\n    display: inline-block;\n    font-family: var(--font-sans, "Segoe UI"), system-ui, sans-serif; font-size: 22px; font-weight: 700;\n    letter-spacing: 0.02em; line-height: 1.15; color: var(--text); white-space: nowrap;\n    user-select: none;\n    animation: logo-bloom 3.5s ease-in-out infinite;\n  }\n  @keyframes logo-bloom {\n    0%, 100% { text-shadow: 0 0 5px var(--accent), 0 0 12px var(--accent), 0 0 24px var(--accent); opacity: .92; }\n    50% { text-shadow: 0 0 8px var(--accent), 0 0 20px var(--accent), 0 0 44px var(--accent); opacity: 1; }\n  }\n  .clicker-row { text-align: center; margin-top: 10px; position: relative; }\n  .clicker-msg {\n    position: absolute; top: -34px; left: 0; right: 0; text-align: center;\n    font-size: 13px; color: var(--accent); opacity: 0; transition: opacity .5s;\n    pointer-events: none; white-space: nowrap;\n  }\n  .clicker-msg.show { opacity: 1; }\n  .clicker {\n    min-width: 120px; height: 42px; padding: 0 18px; border-radius: var(--radius-l);\n    background: var(--surface); border: 1px solid var(--widget); color: var(--text);\n    font-size: 15px; line-height: 1; cursor: pointer; vertical-align: middle;\n    transition: transform .08s, background .15s, border-color .15s;\n  }\n  .clicker:hover { background: var(--widget); }\n  .clicker:active, .clicker.pressed {\n    transform: scale(.9);\n    background: var(--accent); border-color: var(--accent); color: var(--bg);\n  }\n  /* Вкладки переносятся по ширине окна: немецкие подписи не влезали в\n     прежнюю узкую панель и выдавливали FTP за правый край. */\n  .tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }\n  .tab {\n    flex: 0 1 auto; min-width: 0;\n    padding: 8px 18px; border: 1px solid var(--surface); border-radius: var(--radius-m);\n    background: var(--surface); color: var(--text); font-size: 14px; cursor: pointer;\n  }\n  .tab.active { background: var(--accent); color: var(--bg); border-color: var(--accent); }\n  .panel { margin-bottom: 4px; }\n  .actions { margin-top: 16px; display: flex; gap: 8px; align-items: center; }\n  .pb-wrap { margin-top: 14px; height: 10px; border-radius: var(--radius-s); background: var(--surface); overflow: hidden; }\n  #pb { height: 100%; width: 0; background: var(--accent); transition: width .2s; }\n  #pb.indeterminate { width: 30%; animation: slide 1.2s infinite; }\n  @keyframes slide { 0% { margin-left: -30%; } 100% { margin-left: 100%; } }\n  #status { margin-top: 6px; font-size: 13px; height: 18px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n  #log {\n    width: 100%; min-height: 150px; margin-top: 6px; resize: vertical;\n    background: var(--widget); color: var(--text); border: 1px solid var(--surface);\n    border-radius: var(--radius-s); padding: 8px; font-family: var(--font-mono, Consolas), monospace; font-size: 12px;\n  }\n  #warn {\n    display: none; margin-top: 10px; padding: 8px 12px; border-radius: var(--radius-s);\n    background: rgba(255, 180, 84, .15); border: 1px solid var(--warn); color: var(--warn); font-size: 13px;\n  }\n\n  /* ---- кнопка «Скачать»: прогресс и итог внутри самой кнопки ----\n     Слои: .dl-fill (заливка) -> .dl-label (текст) -> .dl-pct (проценты) ->\n     .dl-icon (SVG-результат). Подпись остаётся в потоке - по ней кнопка\n     берёт высоту и ширину, поэтому она одинакова во всех состояниях, а\n     проценты и иконка накладываются поверх и не двигают её размер.\n     Анимации - короткие и пружинистые, как микровзаимодействия Telegram. */\n  .dl {\n    position: relative; overflow: hidden;\n    min-width: 132px; font-weight: 500; line-height: 1.2;\n    transition: background .2s, color .2s, border-color .2s, box-shadow .2s;\n    --dl-ok: #46a758;      /* зелёный Telegram-чата */\n    --dl-err: var(--warn); /* ошибка = цвет предупреждения темы */\n    --dl-fail: #e5484d;    /* ничего не скачалось: тот же красный, что у Telegram */\n    --dl-cancel: var(--text);\n    --dl-spring: cubic-bezier(.2, .9, .25, 1.28); /* лёгкий перелёт */\n  }\n  .dl-fill {\n    position: absolute; inset: 0 auto 0 0; width: var(--dl-pct, 0%);\n    background: var(--widget);   /* фолбэк для WebView2 без color-mix() */\n    background: color-mix(in srgb, var(--accent) 34%, transparent);\n    border-right: 1px solid var(--accent);\n    border-right-color: color-mix(in srgb, var(--accent) 70%, transparent);\n    transition: width .28s cubic-bezier(.4, 0, .2, 1), background .2s;\n    z-index: 0; pointer-events: none;\n  }\n  /* вне прогресса заливки нет: у итога остаётся чистая поверхность */\n  .dl:not(.dl-busy) .dl-fill { display: none; }\n  /* подпись в потоке: из неё кнопка берёт высоту (как у соседней «Отмены»);\n     если сделать её абсолютной, в потоке не останется ничего и высота\n     схлопнется до отступов */\n  .dl-label {\n    position: relative; z-index: 2; display: block;\n    transition: opacity .18s, transform .18s; pointer-events: none;\n  }\n  .dl-pct, .dl-icon {\n    position: absolute; inset: 0; z-index: 2; display: flex;\n    align-items: center; justify-content: center; gap: 6px;\n    transition: opacity .18s, transform .18s; pointer-events: none;\n  }\n  .dl-pct { font-variant-numeric: tabular-nums; opacity: 0; transform: scale(.9); }\n  .dl-icon { opacity: 0; transform: scale(.4) rotate(-14deg); }\n  .dl-icon svg {\n    width: 19px; height: 19px; fill: none; stroke: currentColor;\n    stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round;\n  }\n  /* прогресс: текст уходит, проценты въезжают */\n  .dl.dl-busy .dl-label { opacity: 0; transform: scale(.92); }\n  .dl.dl-busy .dl-pct { opacity: 1; transform: scale(1); }\n  .dl.dl-ok .dl-icon, .dl.dl-err .dl-icon, .dl.dl-warn .dl-icon,\n  .dl.dl-fail .dl-icon, .dl.dl-cancel .dl-icon {\n    opacity: 1; transform: scale(1) rotate(0);\n  }\n  .dl.dl-ok .dl-label, .dl.dl-err .dl-label, .dl.dl-warn .dl-label,\n  .dl.dl-fail .dl-label, .dl.dl-cancel .dl-label, .dl.dl-ok .dl-pct,\n  .dl.dl-err .dl-pct, .dl.dl-warn .dl-pct, .dl.dl-fail .dl-pct,\n  .dl.dl-cancel .dl-pct { opacity: 0; }\n  .dl.dl-ok { color: var(--dl-ok); box-shadow: inset 0 0 0 1px var(--dl-ok); }\n  .dl.dl-err, .dl.dl-warn { color: var(--dl-err); box-shadow: inset 0 0 0 1px var(--dl-err); }\n  .dl.dl-cancel { color: var(--text); color: color-mix(in srgb, var(--dl-cancel) 75%, transparent); }\n  .dl.dl-ok .dl-icon { animation: dl-pop .42s var(--dl-spring); }\n  .dl.dl-err .dl-icon, .dl.dl-warn .dl-icon { animation: dl-shake .42s cubic-bezier(.36, .07, .19, .97); }\n  .dl.dl-cancel .dl-icon { animation: dl-pop .34s var(--dl-spring); }\n  /* полный провал: крест неприлично выпячивается за кнопку и гаснет, поэтому\n     именно этому состоянию нужен overflow: visible - иначе пик срежет рамкой */\n  .dl.dl-fail {\n    overflow: visible; color: var(--dl-fail);\n    box-shadow: inset 0 0 0 1px var(--dl-fail);\n  }\n  .dl.dl-fail .dl-icon { animation: dl-bulge .5s var(--dl-spring); }\n  /* крест крупнее прочих знаков: в покое он уже впритык к краям, а на пике\n     анимации выходит за кнопку - обводку чуть тонше, чтобы не разжиреть */\n  .dl.dl-fail .dl-icon svg { width: 27px; height: 27px; stroke-width: 2; }\n  @keyframes dl-bulge {\n    0% { opacity: 0; transform: scale(.2) rotate(-28deg); }\n    32% { opacity: 1; transform: scale(1.55) rotate(7deg); filter: drop-shadow(0 0 10px var(--dl-fail)); }\n    50% { transform: scale(.84) rotate(-4deg); filter: drop-shadow(0 0 2px var(--dl-fail)); }\n    72% { transform: scale(1.16) rotate(0); filter: drop-shadow(0 0 5px var(--dl-fail)); }\n    100% { opacity: 1; transform: scale(1) rotate(0); filter: none; }\n  }\n  @keyframes dl-pop {\n    0% { opacity: 0; transform: scale(.3) rotate(-16deg); }\n    60% { opacity: 1; transform: scale(1.14) rotate(4deg); }\n    100% { opacity: 1; transform: scale(1) rotate(0); }\n  }\n  @keyframes dl-shake {\n    0% { opacity: 0; transform: scale(.6); }\n    25% { opacity: 1; transform: scale(1) translateX(-4px); }\n    45% { transform: translateX(4px); }\n    65% { transform: translateX(-3px); }\n    85% { transform: translateX(2px); }\n    100% { opacity: 1; transform: scale(1) translateX(0); }\n  }\n  /* пока процент неизвестен, заливка не едет: по ней ходит блик. Сама заливка\n     всегда равна рекорду процента (dlBest), поэтому на новом файле плейлиста\n     не откатывается */\n  .dl.dl-indeterminate::after {\n    /* сплошной градиент + opacity вместо color-mix: работает в любом WebView2 */\n    content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;\n    background: linear-gradient(100deg, transparent 20%, var(--text) 50%, transparent 80%);\n    opacity: .22;\n    transform: translateX(-100%); animation: dl-sheen 1.5s ease-in-out infinite;\n  }\n  @keyframes dl-sheen { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }\n  /* disabled должен гасить кнопку, но не заливку прогресса и не иконку итога */\n  .dl:disabled { opacity: 1; cursor: default; }\n  .dl.dl-busy:disabled { background: var(--surface); color: var(--text); }\n  .dl.dl-busy:disabled:hover { background: var(--surface); color: var(--text); }\n  .dl.dl-ok:disabled:hover, .dl.dl-err:disabled:hover, .dl.dl-warn:disabled:hover,\n  .dl.dl-fail:disabled:hover, .dl.dl-cancel:disabled:hover {\n    background: var(--surface);\n  }\n  @media (prefers-reduced-motion: reduce) {\n    .dl, .dl-fill, .dl-label, .dl-pct, .dl-icon,\n    .dl.dl-indeterminate::after,\n    .dl.dl-ok .dl-icon, .dl.dl-err .dl-icon, .dl.dl-warn .dl-icon,\n    .dl.dl-fail .dl-icon, .dl.dl-cancel .dl-icon { animation: none !important; transition: none !important; }\n  }\n\n  /* ---- ffmpeg bloom-оверлей: дождь поверх темы ---- */\n  #ffmpeg-overlay {\n    position: fixed; inset: 0; z-index: 999; overflow: hidden;\n    display: flex; align-items: center; justify-content: center;\n    background:\n      radial-gradient(130% 110% at 50% 0%, rgba(40, 47, 80, .72) 0%, rgba(20, 22, 44, .82) 55%, rgba(6, 8, 16, .92) 100%);\n    font-family: var(--font-sans, "Segoe UI"), system-ui, sans-serif;\n    -webkit-backdrop-filter: blur(5px);\n    backdrop-filter: blur(5px);\n  }\n  /* дождь (по мотивам codepen jh3y/WyNdMG: капли со случайными CSS-переменными) */\n  #ffmpeg-rain { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 1; }\n  #ffmpeg-rain i {\n    position: absolute; top: -30vh; left: var(--x, 50%);\n    width: 2px; height: var(--len, 14vh); border-radius: 3px;\n    background: linear-gradient(180deg, transparent 0%, rgba(205, 230, 255, .9) 60%, rgba(255, 255, 255, .95) 100%);\n    box-shadow: 0 0 6px rgba(140, 200, 255, .35);\n    opacity: var(--op, .6);\n    animation: rain-fall var(--dur, 1s) linear infinite;\n    animation-delay: var(--delay, 0s);\n  }\n  @keyframes rain-fall {\n    0%   { transform: translateY(-30vh); }\n    100% { transform: translateY(150vh); }\n  }\n\n  #ffmpeg-box { position: relative; z-index: 2; text-align: center; color: #eaf6ff; max-width: 600px; }\n  /* заголовок в собственном «box» с размытием фона, чтобы читался поверх индикатора */\n  #ffmpeg-head {\n    display: inline-block; margin-bottom: 30px; padding: 20px 40px;\n    background: rgba(12, 16, 28, .38);\n    -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px);\n    border-radius: 22px;\n    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .09), 0 10px 40px rgba(0, 0, 0, .35);\n  }\n  #ffmpeg-title {\n    margin: 0 0 6px; font-size: 44px; font-weight: 700; letter-spacing: .04em;\n    color: #fff; animation: ff-title-bloom 3.6s ease-in-out infinite;\n  }\n  @keyframes ff-title-bloom {\n    0%, 100% { text-shadow: 0 0 14px rgba(130, 225, 255, .6), 0 0 34px rgba(90, 190, 240, .35); }\n    50% { text-shadow: 0 0 22px rgba(130, 225, 255, .9), 0 0 60px rgba(90, 190, 240, .6); }\n  }\n  #ffmpeg-sub { font-size: 15px; opacity: .94; margin: 0; line-height: 1.5; max-width: 440px; }\n\n  /* кнопка в стиле hyperspace (codepen mephysto/poKNxoY) */\n  #ffmpeg-dl {\n    background: #fff; position: relative; border: 1px solid transparent;\n    cursor: pointer; padding: 14px 52px; border-radius: 100px; overflow: hidden;\n    font-size: 19px; width: 320px; height: 74px; color: #000;\n  }\n  #ffmpeg-dl.active {\n    background: #03101f; border: 1px solid rgba(255,255,255,.9);\n  }\n  #ffmpeg-dl span {\n    position: relative; z-index: 20; font-size: 1.05em; text-transform: uppercase;\n    font-weight: 700; letter-spacing: .06em; color: #000;\n  }\n  #ffmpeg-dl.active span { color: #fff; }\n  #ffmpeg-dl canvas {\n    z-index: 10; position: absolute; top: 0; left: 0; width: 100%; height: 100%;\n  }\n\n  /* прогресс-кольцо: заполняется по мере скачивания */\n  #ffmpeg-progress { position: relative; width: 170px; height: 170px; margin: 0 auto; }\n  #ffmpeg-ring { width: 170px; height: 170px; transform: rotate(-90deg); display: block; }\n  #ffmpeg-ring circle { fill: none; stroke-width: 9; }\n  #ffmpeg-ring .ring-bg { stroke: rgba(255, 255, 255, .15); }\n  #ffmpeg-ring .ring-fg {\n    stroke: #fff; stroke-linecap: round;\n    stroke-dasharray: 326.7; stroke-dashoffset: 326.7;\n    transition: stroke-dashoffset .25s linear;\n    filter: drop-shadow(0 0 6px rgba(140, 220, 255, .85));\n  }\n  #ffmpeg-ring.ffmpeg-extracting { animation: ring-spin 1.1s linear infinite; }\n  #ffmpeg-ring.ffmpeg-extracting .ring-fg { stroke-dasharray: 40 286.7; }\n  @keyframes ring-spin { from { transform: rotate(-90deg); } to { transform: rotate(270deg); } }\n  #ffmpeg-percent {\n    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n    font-size: 34px; font-weight: 700; color: #fff; text-shadow: 0 0 12px rgba(140, 220, 255, .9);\n  }\n  #ffmpeg-status { margin-top: 26px; font-size: 15px; min-height: 20px; color: #dff3ff; }\n  #ffmpeg-retry {\n    margin-top: 12px; display: none;\n    background: transparent; border: 1px solid rgba(255,255,255,.55); color: #fff;\n    padding: 8px 26px; border-radius: 40px; cursor: pointer; font-size: 14px;\n  }\n  #ffmpeg-retry:hover { background: rgba(255,255,255,.12); }\n  .ffmpeg-hidden { display: none !important; }\n'

APP_JS = '  /* Главное окно (ui_src/app.js). Настройки живут в отдельном окне\n     (ui_src/settings.js), здесь только загрузка, прогресс и журнал.\n     Общие переводы, палитра темы и шрифты - в ui_src/common.js. */\n  var since = 0;\n  var LOG_LINES = 2000; // сколько строк лога держим в textarea\n  var LOG_CHARS = 120000; // порог (~2000 строк) для обрезки без split на каждом poll\n  var pollTimer = 0;\n  var busy = false;\n  var activeTab = "video";\n  var clicks = 0;\n  var uiRev = -1;    // счётчик смен языка/темы/шрифтов в окне настроек\n  var blocked = false;  // открыто ли окно настроек (главное окно приглушено)\n  var ffmpegOverlay = document.getElementById("ffmpeg-overlay");\n  var ffmpegDlBtn = document.getElementById("ffmpeg-dl");\n  var ffmpegRain = document.getElementById("ffmpeg-rain");\n  var ffmpegRing = document.getElementById("ffmpeg-ring");\n  var ffmpegPercent = document.getElementById("ffmpeg-percent");\n  var ffmpegStatus = document.getElementById("ffmpeg-status");\n  var ffmpegRetry = document.getElementById("ffmpeg-retry");\n  var ffmpegFetching = false;\n  var RING_CIRC = 2 * Math.PI * 52;\n\n  /* ---- кнопка-гиперпространство (mephysto/poKNxoY) ---- */\n  var hyperspace = (function hyperspaceButton() {\n    var canvas = ffmpegDlBtn.querySelector("canvas");\n    var ctx = canvas.getContext("2d");\n    var PARTICLES = [];\n    var isGoing = false;\n    var rafId = 0;\n    var W = 0, H = 0, XO = 0, YO = 0;\n    var MAX_Z = 2, MAX_R = 2, Z_SPD = 2;\n\n    function Particle() {\n      this.x = Math.random() * W;\n      this.y = Math.random() * H;\n      this.z = Math.random() * MAX_Z;\n      this.vel = 0.01 * Z_SPD;\n    }\n    Particle.prototype.update = function() { this.z -= this.vel; };\n    Particle.prototype.render = function() {\n      var z = Math.max(this.z, 0.0001);\n      var px = (this.x - XO) / z * 6 + XO;\n      var py = (this.y - YO) / z * 6 + YO;\n      var r = ((MAX_Z - this.z) / MAX_Z) * MAX_R;\n      if (px < 0 || px > W || py < 0 || py > H) this.z = MAX_Z;\n      this.update();\n      ctx.beginPath();\n      ctx.arc(px, py, Math.max(r, 0.4), 0, Math.PI * 2);\n      ctx.fillStyle = "rgba(255,255,255,0.55)";\n      ctx.strokeStyle = "rgba(255,255,255,0.55)";\n      ctx.fill();\n      ctx.stroke();\n    };\n\n    function size() {\n      canvas.width = W = ffmpegDlBtn.offsetWidth;\n      canvas.height = H = ffmpegDlBtn.offsetHeight;\n      XO = W / 2; YO = H / 2;\n      if (W < 10 || H < 10) { canvas.width = W = 640; canvas.height = H = 148; XO = W / 2; YO = H / 2; }\n    }\n\n    // requestAnimationFrame крутится только пока анимация идёт: в простое\n    // это пустой 60 fps впустую (батарея/CPU), поэтому кадр сам себя\n    // останавливает, а play()/resume() снова его запускают.\n    function frame() {\n      ctx.fillStyle = "rgba(0,0,0,0.28)";\n      ctx.fillRect(0, 0, W, H);\n      for (var i = 0; i < PARTICLES.length; i++) PARTICLES[i].render();\n      rafId = isGoing ? requestAnimationFrame(frame) : 0;\n    }\n\n    function play() {\n      isGoing = true;\n      if (!rafId) rafId = requestAnimationFrame(frame);\n    }\n\n    function stop() {\n      isGoing = false;\n      if (rafId) { cancelAnimationFrame(rafId); rafId = 0; }\n      ctx.clearRect(0, 0, W, H);\n    }\n\n    function pause() { if (rafId) { cancelAnimationFrame(rafId); rafId = 0; } }\n    function resume() { if (isGoing) play(); }\n\n    function init() {\n      size();\n      PARTICLES = [];\n      var num = 60;\n      for (var i = 0; i < num; i++) PARTICLES.push(new Particle());\n      window.addEventListener("resize", function() { size(); if (isGoing) play(); });\n    }\n    ffmpegDlBtn.addEventListener("click", function() {\n      if (ffmpegFetching) return;\n      ffmpegFetching = true;\n      play();\n      ffmpegDlBtn.classList.add("active");\n      ffmpegDlBtn.querySelector("span").style.display = "block";\n      setFfmpegProgress(0);\n      showFfmpegProgress();\n      doFfmpegDownload();\n    });\n    setTimeout(init, 50);\n    return { play: play, stop: stop, pause: pause, resume: resume };\n  })();\n\n  /* ---- дождь (по мотивам codepen jh3y/WyNdMG) ---- */\n  (function buildRain() {\n    var frag = document.createDocumentFragment();\n    var drops = 90;\n    for (var i = 0; i < drops; i++) {\n      var d = document.createElement("i");\n      d.style.setProperty("--x", (Math.random() * 100).toFixed(2) + "vw");\n      d.style.setProperty("--len", (9 + Math.random() * 16).toFixed(2) + "vh");\n      d.style.setProperty("--dur", (0.6 + Math.random() * 1.4).toFixed(2) + "s");\n      d.style.setProperty("--delay", (Math.random() * 2.5).toFixed(2) + "s");\n      d.style.setProperty("--op", (0.25 + Math.random() * 0.6).toFixed(2));\n      frag.appendChild(d);\n    }\n    ffmpegRain.appendChild(frag);\n  })();\n\n  function setFfmpegProgress(pct) {\n    var v = Math.max(0, Math.min(100, pct || 0));\n    ffmpegRing.classList.remove("ffmpeg-extracting");\n    ffmpegRing.querySelector(".ring-fg").style.strokeDashoffset = (RING_CIRC * (1 - v / 100)).toFixed(1);\n    ffmpegPercent.textContent = String(Math.round(v)) + "%";\n  }\n  function setFfmpegExtracting() {\n    ffmpegRing.classList.add("ffmpeg-extracting");\n    ffmpegPercent.textContent = "…";\n  }\n  function showFfmpegProgress() {\n    ffmpegDlBtn.classList.add("ffmpeg-hidden");\n    document.getElementById("ffmpeg-progress").classList.remove("ffmpeg-hidden");\n  }\n  function updateFfmpegStatus(text) {\n    ffmpegStatus.classList.remove("ffmpeg-hidden");\n    ffmpegStatus.textContent = text;\n  }\n\n  async function doFfmpegDownload() {\n    try {\n      await pywebview.api.start_ffmpeg_download();\n    } catch (e) {}\n  }\n\n  function applyI18n() {\n    translateStatic();\n    renderClicker();\n    updateDownloadTitle();\n    if (!busy) document.getElementById("status").textContent = t("status.ready");\n  }\n\n  function renderClicker() {\n    var btn = document.getElementById("clicker");\n    btn.textContent = clicks === 0 ? t("clicker.hint") : clicks;\n  }\n  function clickerMessages() {\n    var d = I18N[curLang] || I18N.ru || {};\n    var arr = d["clicker.messages"];\n    if (!Array.isArray(arr) && I18N.ru) arr = I18N.ru["clicker.messages"];\n    return Array.isArray(arr) ? arr : [];\n  }\n  function flashClickerMsg() {\n    var arr = clickerMessages();\n    if (!arr.length) return;\n    var el = document.getElementById("clicker-msg");\n    el.textContent = arr[Math.floor(Math.random() * arr.length)];\n    el.classList.add("show");\n    setTimeout(function() { el.classList.remove("show"); }, 1400);\n  }\n\n  /* ---- кнопка «Скачать»: прогресс внутри кнопки и SVG-результат ----\n     Состояния: idle -> busy (determinate/indeterminate) -> ok|err|cancel -> idle.\n     Итог держим 2 секунды, потом возвращаем «Скачать». Размеры задаёт .dl-label\n     (она в потоке), проценты и иконка накладываются поверх.\n     Процент - рекорд за текущую загрузку: yt-dlp считает его от размера\n     ТЕКУЩЕГО файла, так что в плейлисте значение возвращалось к началу, а на\n     постобработке и вовсе пропадало. dlBest не даёт заливке откатиться, а в\n     неопределённом режиме мы не меняем ни заливку, ни число - только гоним\n     блик, поэтому кнопка не мигает. */\n  var DL_STATES = ["idle", "busy", "ok", "err", "warn", "fail", "cancel"];\n  var DL_ICON = {\n    ok: \'<svg viewBox="0 0 24 24"><path d="M7 10v12"/><path d="M15 5.88 14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2a3.13 3.13 0 0 1 3 3.88Z"/></svg>\',\n    err: \'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.2h.01"/></svg>\',\n    // полный провал: голый крест без круга - заметно отличается от «!» и\n    // крупнее, потому что анимация dl-bulge выталкивает его за края кнопки\n    fail: \'<svg viewBox="0 0 24 24"><path d="M6 6l12 12"/><path d="M18 6 6 18"/></svg>\',\n    cancel: \'<svg viewBox="0 0 24 24"><path d="M8 3h8l5 5v8l-5 5H8l-5-5V8z"/><path d="M8.5 12h7"/></svg>\'\n  };\n  DL_ICON.warn = DL_ICON.err;   // тот же «!», но подпись btn.warn\n  var DL_TITLE = {idle: "btn.download", busy: "btn.downloading", ok: "btn.done",\n                  err: "btn.partial", warn: "btn.warn", fail: "btn.failed",\n                  cancel: "btn.cancelled"};\n  var DL_RESULT = {ok: "ok", error: "err", warn: "warn", failed: "fail", cancelled: "cancel"};\n  var DL_RESET_MS = 2000;\n  var dlState = "idle";\n  var dlBest = 0;         // рекорд процента за загрузку\n  var dlIndeterminate = false;\n  var dlShown = null;     // какой result уже показан, чтобы не мигать после сброса\n  var dlTimer = 0;\n\n  function updateDownloadTitle() {\n    var btn = document.getElementById("download");\n    var key = DL_TITLE[dlState] || "btn.download";\n    btn.title = t(key);\n    btn.setAttribute("aria-label", t(key));\n  }\n  function setDownloadState(state, pct, indeterminate) {\n    if (DL_STATES.indexOf(state) === -1) state = "idle";\n    var btn = document.getElementById("download");\n    if (state !== dlState) {\n      if (state === "busy") dlBest = 0;          // новая загрузка - новый рекорд\n      clearTimeout(dlTimer);\n      dlTimer = 0;\n      DL_STATES.forEach(function(s) { btn.classList.remove("dl-" + s); });\n      btn.classList.add("dl-" + state);\n      btn.querySelector(".dl-icon").innerHTML = DL_ICON[state] || "";\n      dlState = state;\n      if (state === "ok" || state === "err" || state === "warn" ||\n          state === "fail" || state === "cancel") {\n        dlTimer = setTimeout(function() {\n          dlTimer = 0;\n          setDownloadState("idle", 0, false);\n        }, DL_RESET_MS);\n      }\n    }\n    // рекорд только растёт; в неопределённом режиме значение не трогаем\n    if (state === "busy" && !indeterminate) dlBest = Math.max(dlBest, Math.min(100, pct || 0));\n    dlIndeterminate = !!indeterminate;\n    btn.classList.toggle("dl-indeterminate", state === "busy" && dlIndeterminate);\n    // многоточие - только пока процент ещё ни разу не пришёл\n    var text = state !== "busy" ? "" : (dlBest > 0 ? Math.round(dlBest) + "%" : "…");\n    var pctNode = btn.querySelector(".dl-pct");\n    if (pctNode.textContent !== text) pctNode.textContent = text;\n    btn.style.setProperty("--dl-pct", state !== "busy" || dlBest <= 0 ? "0%" : dlBest + "%");\n    updateDownloadTitle();\n  }\n  function setDownloadResult(result) {\n    var state = DL_RESULT[result];\n    if (!state || result === dlShown) return;\n    dlShown = result;\n    setDownloadState(state, 0, false);\n  }\n\n  function setBusy(b) {\n    if (b === busy) return;\n    busy = b;\n    document.getElementById("download").disabled = b;\n    document.getElementById("stop").disabled = !b;\n    ["tab-video", "tab-playlist", "url-video", "url-playlist", "settings-btn", "group"]\n      .forEach(function(id) { document.getElementById(id).disabled = b; });\n  }\n\n  function switchTab(name) {\n    activeTab = name;\n    document.getElementById("tab-video").classList.toggle("active", name === "video");\n    document.getElementById("tab-playlist").classList.toggle("active", name === "playlist");\n    document.getElementById("panel-video").hidden = name !== "video";\n    document.getElementById("panel-playlist").hidden = name !== "playlist";\n    if (!busy) document.getElementById(name === "video" ? "url-video" : "url-playlist").focus();\n  }\n\n  /* ---- окно настроек ------------------------------------------------------\n     Настройки живут в отдельном окне, а пока оно открыто, главное окно не должно\n     принимать клики - поэтому Python вызывает synfSetBlocked(true/false).\n     Настоящей модальности у WebView2 нет: alt-tab и горячие клавиши ОС\n     по-прежнему переключают окна, поэтому оверлей глушим и активный элемент\n     снимаем с фокуса. */\n  function setBlocked(value) {\n    blocked = !!value;\n    var veil = document.getElementById("settings-block");\n    if (veil) veil.hidden = !blocked;\n    // Модальность без второго окна: оверлей ловит клики, а inert - клавиатуру\n    // (иначе Tab и Enter уходят в поля под оверлеем). На старых WebView2, где\n    // inert нет, гасим те же элементы через disabled.\n    var kids = [].slice.call(document.body.children).filter(function(n) { return n !== veil; });\n    if ("inert" in HTMLElement.prototype) {\n      kids.forEach(function(node) { node.inert = blocked; });\n    } else {\n      kids.forEach(function(node) {\n        [].slice.call(node.querySelectorAll("input, select, textarea, button, a[href]"))\n          .forEach(function(el) { el.disabled = blocked; });\n      });\n    }\n    if (blocked && document.activeElement && document.activeElement.blur) {\n      document.activeElement.blur();\n    }\n  }\n  function openSettings() {\n    pywebview.api.open_settings().then(function() { setBlocked(true); });\n  }\n  // Python сообщает, что окно настроек закрыто (в том числе крестиком ОС)\n  function settingsClosed() {\n    setBlocked(false);\n  }\n\n  function scheduleTick(delay) {\n    if (pollTimer) clearTimeout(pollTimer);\n    pollTimer = document.hidden ? 0 : setTimeout(tick, delay);\n  }\n\n  async function tick() {\n    pollTimer = 0;\n    if (typeof pywebview === "undefined") { scheduleTick(300); return; }\n    try {\n      var st = await pywebview.api.poll(since);\n      if (typeof st.log_cursor === "number") since = st.log_cursor;\n      if (st.logs && st.logs.length) {\n        var box = document.getElementById("log");\n        box.value += st.logs.join("\\n") + "\\n";\n        if (box.value.length > LOG_CHARS) {\n          var all = box.value.split("\\n");\n          box.value = all.slice(all.length - LOG_LINES).join("\\n");\n        }\n        box.scrollTop = box.scrollHeight;\n      }\n      setBusy(st.busy);\n      var p = st.progress || {};\n      var bar = document.getElementById("pb");\n      if (p.mode === "indeterminate") { bar.classList.add("indeterminate"); bar.style.width = "30%"; }\n      else { bar.classList.remove("indeterminate"); bar.style.width = (p.value || 0) + "%"; }\n      if (st.busy) {\n        dlShown = null;\n        setDownloadState("busy", p.mode === "indeterminate" ? 0 : (p.value || 0), p.mode === "indeterminate");\n      } else {\n        setDownloadResult(st.result);\n      }\n      document.getElementById("status").textContent = st.status || "";\n      if (st.settings_open !== undefined && st.settings_open !== blocked) {\n        if (st.settings_open) setBlocked(true); else settingsClosed();\n      }\n      if (ffmpegFetching && st.ffmpeg) {\n        var fm = st.ffmpeg;\n        if (fm.downloading || fm.extracting) {\n          showFfmpegProgress();\n          if (fm.extracting) {\n            setFfmpegExtracting();\n            updateFfmpegStatus(t("ffmpeg.extracting"));\n          } else {\n            setFfmpegProgress(fm.pct || 0);\n            updateFfmpegStatus(t("ffmpeg.downloading").replace("{pct}", String(Math.round(fm.pct || 0))));\n          }\n        } else if (fm.ok) {\n          showFfmpegProgress();\n          setFfmpegProgress(100);\n          updateFfmpegStatus(t("ffmpeg.ready"));\n          setTimeout(function() {\n            hyperspace.stop();\n            ffmpegOverlay.classList.add("ffmpeg-hidden");\n            document.getElementById("warn").style.display = "none";\n            document.getElementById("status").textContent = t("status.ready");\n            ffmpegFetching = false;\n          }, 500);\n        } else if (fm.error) {\n          showFfmpegProgress();\n          hyperspace.stop();\n          document.getElementById("ffmpeg-progress").classList.add("ffmpeg-hidden");\n          ffmpegDlBtn.classList.remove("ffmpeg-hidden", "active");\n          updateFfmpegStatus(fm.error);\n          ffmpegRetry.style.display = "inline-block";\n          ffmpegFetching = false;\n        }\n      }\n      // Язык, тема или шрифты сменились в окне настроек: главное окно догоняет\n      // их по тому же счётчику ui_rev, без перезагрузки страницы.\n      if (typeof st.ui_rev === "number" && st.ui_rev !== uiRev) {\n        uiRev = st.ui_rev;\n        if (st.lang && st.lang !== curLang) {\n          curLang = st.lang;\n          applyI18n();\n        }\n        if (st.theme) applyTheme(st.theme);\n        loadFontFaces(fontFacesForTheme());\n      }\n    } catch (e) {}\n    scheduleTick(200);\n  }\n\n  function init() {\n    if (window.__initDone) return;\n    window.__initDone = true;\n    pywebview.api.get_initial().then(function(initData) {\n      curLang = initData.settings.language || "en";\n      if (LANGS.indexOf(curLang) === -1) curLang = "en";\n      FONT_PICK.sans = initData.settings.font_sans || "";\n      FONT_PICK.mono = initData.settings.font_mono || "";\n      applyTheme(initData.settings.theme || "");\n      setDownloadState("idle", 0, false);\n      applyI18n();\n      document.getElementById("group").checked = initData.settings.group_playlist !== false;\n      document.getElementById("status").textContent = t("status.ready");\n      if (!initData.ffmpeg) {\n        document.getElementById("warn").style.display = "block";\n        ffmpegOverlay.classList.remove("ffmpeg-hidden");\n        ffmpegStatus.classList.add("ffmpeg-hidden");\n      }\n      document.getElementById("group").addEventListener("change", function() {\n        pywebview.api.save_setting("group_playlist", this.checked);\n      });\n      // В конфиге загрузки только то, что выбирается в этом окне: папка,\n      // субтитры, качество, кодек и сеть живут в настройках, и Python берёт\n      // их сам - значения в обоих окнах не могут разойтись.\n      document.getElementById("download").addEventListener("click", async function() {\n        var url = document.getElementById(activeTab === "video" ? "url-video" : "url-playlist").value.trim();\n        if (!url) {\n          document.getElementById("status").textContent = activeTab === "video"\n            ? t("status.enter.video") : t("status.enter.playlist");\n          return;\n        }\n        var cfg = {\n          url: url,\n          playlist: activeTab === "playlist",\n          group: document.getElementById("group").checked,\n        };\n        if (!cfg.playlist && /[?&]list=/.test(cfg.url)) {\n          document.getElementById("status").textContent = t("status.playlist.warning");\n        }\n        var res = await pywebview.api.start_download(cfg);\n        if (res && res.error) document.getElementById("status").textContent = res.error;\n      });\n      document.getElementById("stop").addEventListener("click", function() {\n        // yt-dlp ещё дорабатывает файл после запроса остановки, поэтому кнопку\n        // блокируем до реального завершения: итог придёт в poll()\n        this.disabled = true;\n        pywebview.api.stop_download();\n      });\n      ffmpegRetry.addEventListener("click", function() {\n        ffmpegRetry.style.display = "none";\n        ffmpegStatus.classList.add("ffmpeg-hidden");\n        ffmpegDlBtn.classList.remove("ffmpeg-hidden");\n        ffmpegFetching = true;\n        ffmpegDlBtn.classList.add("active");\n        setFfmpegProgress(0);\n        showFfmpegProgress();\n        doFfmpegDownload();\n      });\n      document.getElementById("clicker").addEventListener("click", function() {\n        var btn = document.getElementById("clicker");\n        clicks++;\n        btn.classList.add("pressed");\n        setTimeout(function() { btn.classList.remove("pressed"); }, 120);\n        if (clicks % 500 === 0) flashClickerMsg();\n        renderClicker();\n      });\n      document.getElementById("settings-btn").addEventListener("click", openSettings);\n      ["url-video", "url-playlist"].forEach(function(id) {\n        document.getElementById(id).addEventListener("keydown", function(ev) {\n          if (ev.key === "Enter") document.getElementById("download").click();\n        });\n      });\n      document.getElementById("tab-video").addEventListener("click", function() { switchTab("video"); });\n      document.getElementById("tab-playlist").addEventListener("click", function() { switchTab("playlist"); });\n    }).catch(function(e) { console.error("init error:", e); });\n  }\n  if (window.pywebview !== undefined) { init(); }\n  else { window.addEventListener("pywebviewready", init); }\n  // Пока вкладка/окно скрыты, не опрашиваем Python и не крутим анимацию.\n  document.addEventListener("visibilitychange", function() {\n    if (document.hidden) {\n      if (pollTimer) { clearTimeout(pollTimer); pollTimer = 0; }\n      hyperspace.pause();\n    } else {\n      hyperspace.resume();\n      scheduleTick(50);\n    }\n  });\n  scheduleTick(400);\n'

COMMON_JS = '  /* Общая часть главного окна и окна настроек (ui_src/common.js).\n     Подключается в оба окна, поэтому переводы, палитра темы и шрифты всегда\n     ведут себя одинаково: язык, тему и шрифты меняет окно настроек, а главное\n     окно подхватывает то же самое по счётчику ui_rev из poll(). */\n  var THEMES = __THEMES__;\n  var I18N = __I18N__;\n  var LANGS = Object.keys(I18N).filter(function(k) { return I18N[k] && I18N[k].thisLang; });\n  var curLang = "en";\n  // Активная тема. В окне настроек она есть в селекте #theme, в главном окне\n  // селекта нет - тема приходит из poll(), поэтому держим её здесь: и applyTheme,\n  // и fontFacesForTheme должны знать текущую тему одинаково в обоих окнах.\n  var curTheme = "";\n  var FONTS = { families: [], count: 0, folder: "" };\n  // Выбор шрифтов из настроек (без кавычек) — нужен, чтобы при переключении\n  // темы вернуть шрифт, если у темы нет своих font/font_mono, и чтобы запросить\n  // @font-face именно для этих семейств.\n  var FONT_PICK = { sans: "", mono: "" };\n\n  function t(key) {\n    var d = I18N[curLang] || I18N.ru;\n    if (d && d[key] !== undefined) return d[key];\n    if (I18N.ru[key] !== undefined) return I18N.ru[key];\n    return key;\n  }\n\n  // Переводы разметки, помеченной data-i18n / data-i18n-title. Списки и\n  // подписи полей конкретной страницы дополняют её своими сборщиками.\n  function translateStatic() {\n    document.querySelectorAll("[data-i18n]").forEach(function(el) {\n      el.textContent = t(el.getAttribute("data-i18n"));\n    });\n    document.querySelectorAll("[data-i18n-title]").forEach(function(el) {\n      el.title = t(el.getAttribute("data-i18n-title"));\n    });\n  }\n\n  function applyTheme(key) {\n    if (THEMES[key]) curTheme = key;\n    var c = THEMES[curTheme] || THEMES.scarred_mind || {};\n    function pick(v, d) { return v !== undefined && v !== null ? v : d; }\n    var root = document.documentElement.style;\n    root.setProperty("--bg", pick(c.bg, "#0c1622"));\n    root.setProperty("--surface", pick(c.surface, "#1f2b29"));\n    root.setProperty("--widget", pick(c.widget, "#23444b"));\n    root.setProperty("--text", pick(c.text, "#dcdedd"));\n    root.setProperty("--accent", pick(c.accent, "#628d7c"));\n    root.setProperty("--warn", pick(c.warn, "#ffb454"));\n    root.setProperty("--radius-s", pick(c.radius_s, 6) + "px");\n    root.setProperty("--radius-m", pick(c.radius_m, 8) + "px");\n    root.setProperty("--radius-l", pick(c.radius_l, 12) + "px");\n    root.setProperty("--opacity", pick(c.opacity, 1));\n    setFontVar("--font-sans", c.font ? quoted(c.font) : quoted(FONT_PICK.sans));\n    setFontVar("--font-mono", c.font_mono ? quoted(c.font_mono) : quoted(FONT_PICK.mono));\n    var cssEl = document.getElementById("theme-style");\n    if (!cssEl) {\n      cssEl = document.createElement("style");\n      cssEl.id = "theme-style";\n      document.head.appendChild(cssEl);\n    }\n    cssEl.textContent = c.css || "";\n  }\n\n  function quoted(family) {\n    return family ? \'"\' + String(family).replace(/\\\\/g, "\\\\\\\\").replace(/"/g, \'\\\\"\') + \'"\' : "";\n  }\n  function setFontVar(prop, value) {\n    var root = document.documentElement.style;\n    if (value) root.setProperty(prop, value);\n    else root.removeProperty(prop);\n  }\n  // @font-face лежат в <style id="fonts-style"> (подставляет themes.build_page).\n  // Подменяем содержимое целиком — дубликаты не копятся, страница не грузится\n  // заново, поэтому состояние интерфейса (вкладки, поля, лог) сохраняется.\n  function applyFontCss(css) {\n    var el = document.getElementById("fonts-style");\n    if (!el) {\n      el = document.createElement("style");\n      el.id = "fonts-style";\n      document.head.appendChild(el);\n    }\n    el.textContent = css || "";\n  }\n  function loadFontFaces(families) {\n    var list = (families || []).filter(Boolean).filter(function(f, i, arr) {\n      return arr.indexOf(f) === i;\n    });\n    if (!list.length) { applyFontCss(""); return Promise.resolve(); }\n    return pywebview.api.font_face_css(list)\n      .then(function(css) { applyFontCss(css); })\n      .catch(function(e) { console.error("font faces:", e); });\n  }\n\n  // @font-face для действующей темы и выбранных шрифтов: нужны обоим окнам,\n  // когда шрифт или тема сменились в окне настроек.\n  function fontFacesForTheme() {\n    var th = THEMES[themeKey()] || {};\n    return [th.font, th.font_mono, FONT_PICK.sans, FONT_PICK.mono];\n  }\n  function themeKey() {\n    var sel = document.getElementById("theme");\n    return (sel && sel.value) || curTheme || "";\n  }\n'

SETTINGS_CSS = '  /* Вёрстка окна настроек: шапка, список разделов слева, содержимое справа,\n     полоса журнала снизу. Палитра, шрифты и скругления — от темы, структура\n     и отступы — здесь, чтобы окно выглядело одинаково в любой теме. */\n  body {\n    display: flex; flex-direction: column;\n    height: 100vh; padding: 0; overflow: hidden;\n  }\n\n  .win-head {\n    flex: none;\n    display: flex; align-items: center; justify-content: space-between; gap: 12px;\n    padding: 12px 14px;\n    border-bottom: 1px solid var(--surface);\n  }\n  .win-title { font-size: 16px; font-weight: 600; }\n\n  .win-body { flex: 1 1 auto; display: flex; min-height: 0; }\n\n  .nav {\n    flex: 0 0 190px; display: flex; flex-direction: column; gap: 4px;\n    padding: 12px 8px; overflow-y: auto;\n    border-right: 1px solid var(--surface);\n  }\n  .nav-item {\n    text-align: left; width: 100%; padding: 9px 12px;\n    background: transparent; border: 1px solid transparent; color: var(--text);\n    border-radius: var(--radius-m); font-size: 14px;\n    transition: background .15s, color .15s, border-color .15s;\n  }\n  .nav-item:hover { background: var(--surface); color: var(--text); }\n  .nav-item.active { background: var(--accent); color: var(--bg); border-color: var(--accent); }\n\n  .section {\n    flex: 1 1 auto; min-width: 0;\n    padding: 14px 18px 22px; overflow-y: auto;\n  }\n  /* поля идут плотнее, чем в старой панели: окно широкое, места много */\n  .section label { margin-top: 12px; }\n\n  .win-log {\n    flex: none; display: block;\n    width: 100%; height: 58px; margin: 0; padding: 8px 14px; resize: none;\n    border: 0; border-top: 1px solid var(--surface); border-radius: 0;\n    background: var(--surface); color: var(--text);\n    font-family: var(--font-mono, Consolas), monospace; font-size: 12px;\n    overflow-y: auto;\n  }\n\n  @media (max-width: 560px) {\n    .nav { flex-basis: 140px; }\n  }\n'

SETTINGS_JS = '  /* Окно настроек (ui_src/settings.js).\n     Всё содержимое рисуется из схемы (__SETTINGS_SCHEMA__, settings_schema.py):\n     список разделов слева, поля справа. Здесь только то, чего схема знать\n     не может - что делает кнопка, как поле применяется и чем наполняется\n     пояснение. Текстовые поля сохраняются по событию change (потеря фокуса/\n     Enter), чтобы не писать в settings.json на каждый символ. */\n  var SETTINGS_SCHEMA = __SETTINGS_SCHEMA__;\n  var transAvailability = { ffmpeg: true, avail: [] };\n  var since = 0;           // курсор журнала: с какого места продолжать\n  var LOG_LINES = 2000;    // сколько строк журнала держим\n  var LOG_CHARS = 120000;  // порог обрезки без split на каждом poll\n  var pollTimer = 0;\n  var uiRev = -1;          // счётчик смен языка/темы/шрифтов со стороны Python\n  var fontsRev = -1;       // счётчик пересканирования шрифтов\n  var activeSection = "";\n\n  var panelFields = {};    // путь настройки -> {spec, nodes, input, range}\n  var panelButtons = {};   // id кнопки -> элемент\n  var noteFillers = {};    // note_source -> нужно перерисовывать\n  var customSave = {};     // путь настройки -> поле со своим обработчиком\n  // обёртки (блок .settings-box, строка .range-row) с полями внутри: если все\n  // поля скрыты, пустая рамка и пустая строка тоже убираются, иначе в разделе\n  // FTP остаётся рамка «Подключение» с пустым содержимым\n  var panelWrappers = [];  // [{el, keys}]\n\n  function el(tag, cls, attrs) {\n    var node = document.createElement(tag);\n    if (cls) node.className = cls;\n    if (Array.isArray(attrs)) {\n      attrs.forEach(function(n) { node.appendChild(n); });\n    } else if (attrs) {\n      Object.keys(attrs).forEach(function(k) {\n        if (attrs[k] !== undefined && attrs[k] !== null) node.setAttribute(k, attrs[k]);\n      });\n    }\n    return node;\n  }\n  function fieldSpec(path) {\n    var groups = SETTINGS_SCHEMA.groups;\n    for (var i = 0; i < groups.length; i++) {\n      var fields = groups[i].fields;\n      for (var j = 0; j < fields.length; j++) {\n        if (fields[j].path === path) return fields[j];\n      }\n    }\n    return null;\n  }\n  function fieldOptions(path) {\n    var spec = fieldSpec(path);\n    return (spec && spec.options) || [];\n  }\n  // Наполнение <select>: opts = [["value", "i18n.key"], ...]. keepValue=true\n  // сохраняет выбор - список пересобирается при смене языка и при первой\n  // отрисовке, когда значения из настроек ещё нет. Если прежнего значения в\n  // списке не оказалось, берём первый вариант, чтобы поле не осталось пустым\n  // (так же поступает buildThemeOptions).\n  function fillSelectNode(sel, opts, keepValue) {\n    if (!sel || !opts || !opts.length) return;\n    if (!keepValue) keepValue = sel.value;\n    sel.innerHTML = "";\n    opts.forEach(function(o) {\n      var opt = document.createElement("option");\n      opt.value = o[0];\n      opt.textContent = t(o[1]);\n      sel.appendChild(opt);\n    });\n    sel.value = keepValue;\n    if (sel.value === "") {\n      var first = sel.querySelector("option");\n      sel.value = first ? first.value : "";\n    }\n  }\n  function fillSelect(id, opts, keepValue) {\n    fillSelectNode(document.getElementById(id), opts, keepValue);\n  }\n  function caption(key, cls) {\n    var node = el("span", cls, {"data-i18n": key});\n    node.textContent = t(key);\n    return node;\n  }\n  function labelNode(spec) {\n    var node = el("label", null, {for: spec.dom, "data-i18n": spec.label});\n    node.textContent = t(spec.label);\n    if (spec.title) {\n      node.setAttribute("data-i18n-title", spec.title);\n      node.title = t(spec.title);\n    }\n    return node;\n  }\n\n  // Одно поле схемы -> узлы и, если поле редактируемое, input (+range-зеркало).\n  function renderField(spec) {\n    if (spec.type === "actions") {\n      var buttons = spec.buttons.map(function(b) {\n        var btn = el("button", null, {type: "button", id: b.dom});\n        if (b.icon) {\n          var ico = el("span", "ta-ico");\n          ico.textContent = b.icon;\n          btn.appendChild(ico);\n        }\n        btn.appendChild(caption(b.label));\n        panelButtons[b.dom] = btn;\n        return btn;\n      });\n      // в строке кнопки не оборачиваем: строку собирает renderWindow\n      if (spec.row !== undefined && spec.row !== null) return {nodes: buttons};\n      return {nodes: [el("div", spec.row_class || (spec.browse_dest ? "row" : "theme-actions"), buttons)]};\n    }\n    if (spec.type === "note") {\n      var note = el(spec.inline ? "span" : "div", "note", {id: spec.dom});\n      if (spec.hidden) note.hidden = true;\n      // перерисовываем при правке настроек только те пояснения, чьё содержимое\n      // зависит от значения поля (остальные наполняют свои команды)\n      if (NOTE_FILLERS[spec.note_source]) noteFillers[spec.note_source] = true;\n      return {nodes: [note]};\n    }\n    if (spec.type === "bool" && spec.check) {\n      var check = el("div", "check");\n      var box = el("input", null, {type: "checkbox", id: spec.dom});\n      check.appendChild(box);\n      check.appendChild(caption(spec.label));\n      return {nodes: [check], input: box};\n    }\n    var nodes = [labelNode(spec)];\n    var input;\n    if (spec.type === "choice") {\n      input = el("select", null, {id: spec.dom});\n      // опции из схемы наполняем сразу: иначе у поля без своей функции\n      // (например ftp.mode) список остался бы пустым\n      fillSelectNode(input, spec.options, true);\n    } else if (spec.type === "int") {\n      input = el("input", null, {type: "number", id: spec.dom, min: spec.min, max: spec.max, step: spec.step});\n    } else {\n      input = el("input", null, {type: "text", id: spec.dom});\n      input.setAttribute("spellcheck", "false");\n      if (spec.type === "password") input.setAttribute("autocomplete", "off");\n      if (spec.placeholder) input.placeholder = spec.placeholder;\n    }\n    nodes.push(input);\n    var range = null;\n    if (spec.mirror === "range" && spec.dom_range) {\n      range = el("input", null, {type: "range", id: spec.dom_range, min: spec.min, max: spec.max, step: spec.step});\n      nodes.splice(1, 0, range);\n    }\n    return {nodes: nodes, input: input, range: range};\n  }\n\n  // Разделы окна: слева кнопки, справа содержимое полей. Внутри раздела рамки\n  // блоков и строки собираются теми же правилами, что были у вкладок панели.\n  function renderWindow() {\n    var nav = document.getElementById("settings-nav");\n    var host = document.getElementById("settings-sections");\n    nav.innerHTML = "";\n    host.innerHTML = "";\n    panelWrappers = [];\n    SETTINGS_SCHEMA.groups.forEach(function(group, gi) {\n      var item = el("button", gi ? "nav-item" : "nav-item active", {type: "button", id: "nav-" + group.id});\n      item.appendChild(caption(group.label));\n      item.addEventListener("click", function() { switchSection(group.id); });\n      nav.appendChild(item);\n\n      var section = el("div", null, {id: "section-" + group.id, role: "tabpanel"});\n      if (gi) section.hidden = true;\n      var out = [];         // узлы раздела\n      var boxNodes = null;  // узлы текущего блока\n      var boxKeys = null;   // пути полей блока\n      var rowNodes = null;  // узлы текущей строки\n      var rowKeys = null;   // пути полей строки\n      var rowIdx = null;\n      var rowCls = null;\n      var boxName = null;\n      function wrap(list, node, keys) {\n        list.push(node);\n        panelWrappers.push({el: node, keys: keys});\n      }\n      function flushRow() {\n        if (rowNodes) {\n          wrap(boxNodes || out, el("div", rowCls, rowNodes), rowKeys);\n          rowNodes = rowKeys = null; rowIdx = rowCls = null;\n        }\n      }\n      function flushBox() {\n        flushRow();\n        if (boxNodes) {\n          wrap(out, el("div", "settings-box", boxNodes), boxKeys);\n          boxNodes = boxKeys = null;\n        }\n      }\n      group.fields.forEach(function(spec) {\n        if (spec.in_panel === false) return;\n        if ((spec.box || null) !== boxName) {\n          flushBox();\n          boxName = spec.box || null;\n          if (boxName) { boxNodes = [caption(group.boxes[boxName], "settings-box-title")]; boxKeys = []; }\n        }\n        var part = renderField(spec);\n        var key = spec.path || spec.dom;\n        if (boxKeys) boxKeys.push(key);\n        if (spec.row !== undefined && spec.row !== null) {\n          // поля с одинаковым row встают в одну строку (label + input)\n          if (rowNodes && spec.row !== rowIdx) flushRow();\n          if (!rowNodes) { rowNodes = []; rowKeys = []; rowIdx = spec.row; rowCls = spec.row_class || "range-row"; }\n          rowKeys.push(key);\n          part.nodes.forEach(function(n) { rowNodes.push(n); });\n        } else {\n          flushRow();\n          var list = boxNodes || out;\n          part.nodes.forEach(function(n) { list.push(n); });\n        }\n        panelFields[key] = {spec: spec, nodes: part.nodes, input: part.input, range: part.range};\n      });\n      flushBox();\n      out.forEach(function(n) { section.appendChild(n); });\n      host.appendChild(section);\n    });\n    activeSection = SETTINGS_SCHEMA.groups.length ? SETTINGS_SCHEMA.groups[0].id : "";\n  }\n\n  function switchSection(name) {\n    SETTINGS_SCHEMA.groups.forEach(function(group) {\n      document.getElementById("section-" + group.id).hidden = group.id !== name;\n      document.getElementById("nav-" + group.id).classList.toggle("active", group.id === name);\n    });\n    activeSection = name;\n  }\n\n  // -- списки значений полей -------------------------------------------------\n  function buildThemeOptions() {\n    var sel = document.getElementById("theme");\n    var keep = sel.value;\n    sel.innerHTML = "";\n    Object.keys(THEMES).forEach(function(k) {\n      var th = THEMES[k] || {};\n      if (th.hidden === true) return;\n      var opt = document.createElement("option");\n      opt.value = k;\n      var label = (I18N[curLang] || I18N.ru || {})["theme_" + k];\n      if (label === undefined && (I18N.ru || {})["theme_" + k] !== undefined) {\n        label = I18N.ru["theme_" + k];\n      }\n      if (label === undefined) label = th.label || k;\n      if (th.warnings && th.warnings.length) {\n        label += " ⚠";\n        opt.title = t("theme.meta.broken") + "\\n" + th.warnings.join("\\n");\n      }\n      opt.textContent = label;\n      sel.appendChild(opt);\n    });\n    sel.value = keep;\n    if (sel.value === "") {\n      var first = sel.querySelector("option");\n      sel.value = first ? first.value : "";\n    }\n    updateThemeMeta();\n  }\n\n  // Метаданные темы (автор/версия) и предупреждения валидации theme.json.\n  function updateThemeMeta() {\n    var box = document.getElementById("theme-meta");\n    if (!box) return;\n    var sel = document.getElementById("theme");\n    var th = THEMES[sel.value] || {};\n    var parts = [];\n    if (th.label) parts.push(th.label);\n    if (th.author) parts.push(t("theme.meta.author").replace("{name}", th.author));\n    if (th.version) parts.push(t("theme.meta.version").replace("{v}", th.version));\n    box.textContent = parts.join(" · ");\n    box.hidden = parts.length === 0;\n  }\n  function buildSubsOptions() { fillSelect("subs", fieldOptions("dl.subtitles")); }\n  function buildQualOptions() { fillSelect("qual", fieldOptions("dl.quality")); }\n  function buildTranscodeOptions() {\n    var sel = document.getElementById("transcode");\n    var prev = sel.value;\n    sel.innerHTML = "";\n    var missing = [];\n    fieldOptions("dl.transcode").forEach(function(pair) {\n      var o = document.createElement("option");\n      o.value = pair[0];\n      var label = t(pair[1]);\n      if (pair[0] !== "none" && (!transAvailability.ffmpeg || transAvailability.avail.indexOf(pair[0]) === -1)) {\n        o.disabled = true;\n        missing.push(label);\n        o.textContent = label + " " + t("trans.unavailable");\n      } else {\n        o.textContent = label;\n      }\n      sel.appendChild(o);\n    });\n    sel.value = prev;\n    var note = document.getElementById("transcode-note");\n    if (!transAvailability.ffmpeg) {\n      note.textContent = t("trans.note.noffmpeg");\n    } else if (missing.length) {\n      note.textContent = t("trans.note.missing") + missing.join(", ") + ".";\n    } else {\n      note.textContent = "";\n    }\n  }\n  function buildLangOptions() {\n    fillSelect("lang", LANGS.map(function(k) { return [k, I18N[k]["thisLang"]]; }));\n  }\n\n  // Списки шрифтов: "" = системный. Семейства приходят с Python (папка fonts).\n  function buildFontOptions() {\n    var families = (FONTS && FONTS.families) || [];\n    var monoFirst = (FONTS && FONTS.mono) || [];\n    var monoAll = monoFirst.concat(families.filter(function(f) {\n      return monoFirst.indexOf(f) === -1;\n    }));\n    [["font-sans", families], ["font-mono", monoAll]].forEach(function(pair) {\n      var sel = document.getElementById(pair[0]);\n      if (!sel) return;\n      var keep = sel.value;\n      sel.innerHTML = "";\n      var sys = document.createElement("option");\n      sys.value = "";\n      sys.textContent = t("sheet.font.system");\n      sel.appendChild(sys);\n      pair[1].forEach(function(f) {\n        var o = document.createElement("option");\n        o.value = f;\n        o.textContent = f;\n        sel.appendChild(o);\n      });\n      sel.value = keep;\n    });\n    updateFontNote();\n  }\n  function updateFontNote() {\n    var box = document.getElementById("font-note");\n    if (!box) return;\n    if ((FONTS && FONTS.count) > 0) { box.textContent = ""; box.hidden = true; return; }\n    box.textContent = t("sheet.font.hint").replace("{path}", (FONTS && FONTS.folder) || "");\n    box.hidden = false;\n  }\n\n  // Пересборка списков, опции которых пришли прямо из схемы (ftp.mode и т.п.).\n  // Поля со своей логикой (dl.transcode с недоступными кодировщиками) дальше\n  // переопределяются своими сборщиками.\n  function fillSchemaChoices() {\n    Object.keys(panelFields).forEach(function(key) {\n      var f = panelFields[key], spec = f.spec;\n      if (spec.type !== "choice" || !spec.options) return;\n      fillSelectNode(f.input, spec.options, true);\n    });\n  }\n\n  function applyI18n() {\n    translateStatic();\n    // списки из схемы переводим первыми, дальше их уточняют сборщики полей\n    fillSchemaChoices();\n    buildThemeOptions();\n    buildSubsOptions();\n    buildQualOptions();\n    buildTranscodeOptions();\n    buildLangOptions();\n    buildFontOptions();\n    document.getElementById("lang").value = curLang;\n    document.documentElement.lang = curLang;\n  }\n\n  // -- команды кнопок и наполнение пояснений --------------------------------\n  // В схеме у кнопки есть dom и подпись, здесь - только действие.\n  var ACTIONS = {\n    "reload-themes": function() { reloadThemes(); },\n    "open-themes": function() { openThemesFolder(); },\n    "reload-fonts": function() { reloadFonts(); },\n    "download-fonts": function() { downloadFonts(); },\n    "open-fonts": function() { openFontsFolder(); },\n    "browse": async function() {\n      var picked = await pywebview.api.browse_folder();\n      if (picked) {\n        panelFields["ui.dest"].input.value = picked;\n        pywebview.api.set_dest(picked);\n      }\n    },\n    "ftp-test": async function() {\n      var note = document.getElementById("ftp-test-note");\n      note.className = "note";\n      note.textContent = t("sheet.ftp.testing");\n      var res = await pywebview.api.test_ftp();\n      if (res && res.ok) {\n        note.className = "note ok";\n        note.textContent = t("sheet.ftp.test_ok").replace("{host}", res.host);\n      } else {\n        note.className = "note bad";\n        note.textContent = (res && res.error) || t("sheet.ftp.test_fail");\n      }\n    }\n  };\n  var NOTE_FILLERS = {ftpDirNote: updateFtpDirNote};\n  function refreshNotes() {\n    Object.keys(noteFillers).forEach(function(src) { NOTE_FILLERS[src](); });\n  }\n  function updateFtpDirNote() {\n    var dir = panelFields["ftp.dir"].input.value.trim();\n    var note = document.getElementById("ftp-dir-note");\n    note.textContent = dir ? t("sheet.ftp.dir.ok") : t("sheet.ftp.dir.empty");\n  }\n\n  // -- значения и сохранение -------------------------------------------------\n  function fillSettings(settings, initData) {\n    Object.keys(panelFields).forEach(function(key) {\n      var f = panelFields[key], spec = f.spec, node = f.input;\n      if (!node) return;\n      var value = spec.value_source ? initData[spec.value_source] : settings[spec.setting];\n      if (spec.type === "bool") node.checked = value !== false && !!value;\n      else if (spec.type === "text" || spec.type === "password") node.value = value || node.placeholder || "";\n      else node.value = value || spec.default;\n      if (f.range) f.range.value = node.value;\n    });\n  }\n\n  function bindSettings() {\n    Object.keys(panelFields).forEach(function(key) {\n      var f = panelFields[key], spec = f.spec, node = f.input;\n      if (!node || customSave[key]) return;\n      node.addEventListener("change", function() {\n        var value = spec.type === "bool" ? node.checked : node.value.trim();\n        if (f.range) f.range.value = value;\n        if (spec.setting) pywebview.api.save_setting(spec.setting, value);\n        // папка загрузки - не настройка: Python помнит её до конца сеанса\n        if (spec.path === "ui.dest") pywebview.api.set_dest(value);\n        applyVisibility();\n        refreshNotes();\n      });\n      if (f.range) {\n        f.range.addEventListener("input", function() {\n          node.value = this.value;\n          if (spec.setting) pywebview.api.save_setting(spec.setting, this.value);\n        });\n      }\n    });\n    Object.keys(ACTIONS).forEach(function(dom) {\n      if (panelButtons[dom]) panelButtons[dom].addEventListener("click", function() { ACTIONS[dom](); });\n    });\n  }\n\n  // Условия видимости описаны в схеме (visible_if) - здесь только их применение.\n  function applyVisibility() {\n    Object.keys(panelFields).forEach(function(key) {\n      var cond = panelFields[key].spec.visible_if;\n      if (!cond) return;\n      var src = panelFields[cond.key];\n      var show = !!(src && src.input && src.input.checked) === !!cond.equals;\n      panelFields[key].nodes.forEach(function(node) { node.hidden = !show; });\n    });\n    // Рамка блока и строка прячутся, когда скрыты все поля внутри: иначе в\n    // разделе FTP остаётся пустая рамка «Подключение», а в строках - пустые\n    // отступы от margin.\n    panelWrappers.forEach(function(box) {\n      var any = box.keys.some(function(key) {\n        var f = panelFields[key];\n        return f && f.nodes.some(function(node) { return !node.hidden; });\n      });\n      box.el.hidden = !any;\n    });\n  }\n\n  // Поля с собственным поведением: тема, язык, шрифты.\n  function onChange(path, fn) {\n    var f = panelFields[path];\n    if (!f || !f.input) return;\n    customSave[path] = true;\n    f.input.addEventListener("change", function() { fn(f.input, f.spec); });\n  }\n\n  // -- темы и шрифты ---------------------------------------------------------\n  function reloadThemes() {\n    var btn = document.getElementById("reload-themes");\n    pywebview.api.reload_themes().then(function(newThemes) {\n      THEMES = newThemes;\n      buildThemeOptions();\n      applyI18n();\n      if (btn) {\n        var lbl = btn.querySelector("[data-i18n]");\n        if (lbl) {\n          var txt = lbl.textContent;\n          lbl.textContent = "✓";\n          btn.classList.add("done");\n          setTimeout(function() {\n            lbl.textContent = txt;\n            btn.classList.remove("done");\n          }, 900);\n        }\n      }\n    }).catch(function(e) { console.error("reload themes:", e); });\n  }\n  function openThemesFolder() {\n    pywebview.api.open_themes_folder();\n  }\n  // Шрифт применяется подменой блока #fonts-style - без перезагрузки страницы\n  // и без потери состояния окна. Главное окно подхватит выбор по ui_rev.\n  function setFont(id, value) {\n    var slot = id === "font-mono" ? "mono" : "sans";\n    pywebview.api.set_font(id === "font-mono" ? "font_mono" : "font_sans", value)\n      .then(function(r) {\n        if (r && r.error) { console.error("set font:", r.error); return; }\n        FONT_PICK[slot] = value || "";\n        if (r && r.css !== undefined) applyFontCss(r.css);\n        var th = THEMES[themeKey()] || {};\n        var thFont = slot === "mono" ? th.font_mono : th.font;\n        setFontVar(slot === "mono" ? "--font-mono" : "--font-sans",\n                   quoted(thFont || FONT_PICK[slot]));\n      })\n      .catch(function(e) { console.error("set font:", e); });\n  }\n  function reloadFonts() {\n    pywebview.api.reload_fonts()\n      .then(function(r) {\n        if (r && r.fonts) FONTS = r.fonts;\n        if (r && r.css !== undefined) applyFontCss(r.css);\n        buildFontOptions();\n        applyI18n();\n      })\n      .catch(function(e) { console.error("reload fonts:", e); });\n  }\n  // Докачка шрифтов из сети: кнопка busy на всё время, прогресс в note.\n  // Список обновится сам, когда Python поднимет fonts_rev (см. tick).\n  function downloadFonts() {\n    var btn = document.getElementById("download-fonts");\n    var note = document.getElementById("font-dl-note");\n    pywebview.api.download_fonts()\n      .then(function(res) {\n        if (res === "busy") { setFontDlNote(t("font.dl.busy")); return; }\n        btn.classList.add("busy");\n        btn.disabled = true;\n        setFontDlNote(t("font.dl.start"));\n      })\n      .catch(function(e) {\n        btn.classList.remove("busy");\n        btn.disabled = false;\n        setFontDlNote(t("font.dl.fail").replace("{names}", String(e)));\n      });\n  }\n  function setFontDlNote(text) {\n    var note = document.getElementById("font-dl-note");\n    if (!note) return;\n    note.textContent = text || "";\n    note.hidden = !text;\n  }\n  function fontDlState(st) {\n    var d = st.fonts_dl;\n    if (!d) return;\n    var btn = document.getElementById("download-fonts");\n    if (d.downloading) {\n      if (btn) { btn.classList.add("busy"); btn.disabled = true; }\n      setFontDlNote(t("font.dl.progress").replace("{pct}", String(Math.round(d.pct || 0))));\n    } else if (btn && btn.disabled) {\n      btn.classList.remove("busy");\n      btn.disabled = false;\n      setFontDlNote(d.error ? t("font.dl.fail").replace("{names}", String(d.error)) : "");\n    }\n  }\n  function openFontsFolder() {\n    pywebview.api.open_fonts_folder();\n  }\n\n  // -- журнал и синхронизация с главным окном -------------------------------\n  function scheduleTick(delay) {\n    if (pollTimer) clearTimeout(pollTimer);\n    pollTimer = setTimeout(tick, delay);\n  }\n\n  async function tick() {\n    pollTimer = 0;\n    if (typeof pywebview === "undefined") { scheduleTick(300); return; }\n    try {\n      var st = await pywebview.api.poll_settings(since);\n      if (typeof st.log_cursor === "number") since = st.log_cursor;\n      if (st.logs && st.logs.length) {\n        var box = document.getElementById("log");\n        box.value += st.logs.join("\\n") + "\\n";\n        if (box.value.length > LOG_CHARS) {\n          var all = box.value.split("\\n");\n          box.value = all.slice(all.length - LOG_LINES).join("\\n");\n        }\n        box.scrollTop = box.scrollHeight;\n      }\n      fontDlState(st);\n      // Язык, тема или шрифты сменились в этом же окне: главное окно ждёт тот\n      // же счётчик, поэтому обновляемся оба.\n      if (typeof st.ui_rev === "number" && st.ui_rev !== uiRev) {\n        uiRev = st.ui_rev;\n        if (st.lang && st.lang !== curLang) {\n          curLang = st.lang;\n          applyI18n();\n        }\n        if (st.theme) applyTheme(st.theme);\n        loadFontFaces(fontFacesForTheme());\n      }\n      // Шрифты докачались на стороне Python: перерисовываем списки и @font-face.\n      if (typeof st.fonts_rev === "number" && st.fonts_rev !== fontsRev) {\n        fontsRev = st.fonts_rev;\n        reloadFonts();\n      }\n    } catch (e) {}\n    scheduleTick(400);\n  }\n\n  function init() {\n    if (window.__initDone) return;\n    window.__initDone = true;\n    pywebview.api.get_initial().then(function(initData) {\n      curLang = initData.settings.language || "en";\n      if (LANGS.indexOf(curLang) === -1) curLang = "en";\n      transAvailability = { ffmpeg: !!initData.ffmpeg, avail: initData.transcoders || [] };\n      FONTS = initData.fonts || FONTS;\n      FONT_PICK.sans = initData.settings.font_sans || "";\n      FONT_PICK.mono = initData.settings.font_mono || "";\n      renderWindow();\n      applyI18n();\n      fillSettings(initData.settings, initData);\n      applyTheme(themeKey());\n      // Поля с собственным поведением помечаются customSave ДО bindSettings(),\n      // иначе к теме/языку/шрифтам привяжется ещё и общий обработчик и каждый\n      // выбор запишется в settings.json дважды.\n      // тема: часть тем со своим entry собирается в Python (полный rebuild\n      // обоих окон), остальные применяются на лету\n      onChange("ui.theme", function(node, spec) {\n        updateThemeMeta();\n        var th = THEMES[node.value] || {};\n        if (th.entry) {\n          pywebview.api.set_theme(node.value);\n          return;\n        }\n        applyTheme(node.value);\n        pywebview.api.save_setting(spec.setting, node.value);\n        if (th.font || th.font_mono) {\n          loadFontFaces(fontFacesForTheme());\n        }\n      });\n      onChange("ui.language", function(node, spec) {\n        curLang = node.value;\n        applyI18n();\n        buildFontOptions();   // подпись «системный» в списках шрифтов тоже переводится\n        updateThemeMeta();\n        applyTheme(themeKey());\n        pywebview.api.save_setting(spec.setting, node.value);\n      });\n      onChange("ui.font_sans", function(node) { setFont("font-sans", node.value); });\n      onChange("ui.font_mono", function(node) { setFont("font-mono", node.value); });\n      bindSettings();\n      applyVisibility();\n      refreshNotes();\n      document.getElementById("settings-close").addEventListener("click", function() {\n        pywebview.api.close_settings();\n      });\n      document.addEventListener("keydown", function(ev) {\n        if (ev.key === "Escape") pywebview.api.close_settings();\n      });\n    }).catch(function(e) { console.error("init error:", e); });\n  }\n\n  if (window.pywebview !== undefined) { init(); }\n  else { window.addEventListener("pywebviewready", init); }\n  scheduleTick(400);\n'

BASE_TEMPLATE = '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<title>Synfronia</title>\n<style>\n  :root {\n    --bg: #0c1622; --surface: #1f2b29; --widget: #23444b;\n    --text: #dcdedd; --accent: #628d7c; --warn: #ffb454;\n    --radius-s: 6px; --radius-m: 8px; --radius-l: 12px; --opacity: 1;\n  }\n  :root { __THEME_ROOT__ }\n</style>\n<style id="fonts-style">__FONTS_CSS__</style>\n<style id="theme-style">__THEME_CSS__</style>\n<style>\n__APP_CSS__\n</style>\n<style>\n__MAIN_CSS__\n</style>\n</head>\n<body>\n\n<!-- SLOT:head -->\n<div class="head">\n    <div class="brand">\n      <h1 class="logo">Synfronia</h1>\n      <div class="sub" data-i18n="ui.sub">Скачивание видео и плейлистов YouTube (yt-dlp)</div>\n    </div>\n    <button type="button" id="settings-btn" class="icon-btn" data-i18n-title="ui.settings" title="Настройки">&#x2699;&#xFE0E;</button>\n  </div>\n<!-- /SLOT:head -->\n\n\n  \n<!-- SLOT:tabs -->\n<div class="tabs">\n    <button type="button" id="tab-video" class="tab active" data-i18n="tab.video">Видео</button>\n    <button type="button" id="tab-playlist" class="tab" data-i18n="tab.playlist">Плейлист</button>\n  </div>\n<!-- /SLOT:tabs -->\n\n\n  \n<!-- SLOT:panel-video -->\n<div id="panel-video" class="panel">\n    <label for="url-video" data-i18n="url.video.label">Ссылка на видео:</label>\n    <input type="text" id="url-video" placeholder="https://www.youtube.com/watch?v=…" autofocus>\n  </div>\n<!-- /SLOT:panel-video -->\n\n\n  \n<!-- SLOT:panel-playlist -->\n<div id="panel-playlist" class="panel" hidden>\n    <label for="url-playlist" data-i18n="url.playlist.label">Ссылка на плейлист:</label>\n    <input type="text" id="url-playlist" placeholder="https://www.youtube.com/playlist?list=…">\n    <div class="check"><input type="checkbox" id="group"><span data-i18n="group.label">Сгруппировать: плейлист в подпапку с его названием</span></div>\n  </div>\n<!-- /SLOT:panel-playlist -->\n\n\n  \n<!-- SLOT:warn -->\n<div id="warn" data-i18n="warn.ffmpeg">ffmpeg не найден — слияние, субтитры, метаданные и перекодировка будут недоступны.</div>\n<!-- /SLOT:warn -->\n\n\n  \n<!-- SLOT:ffmpeg-overlay -->\n<div id="ffmpeg-overlay" class="ffmpeg-hidden">\n    <div id="ffmpeg-rain"></div>\n    <div id="ffmpeg-box">\n      <div id="ffmpeg-head">\n        <div id="ffmpeg-title">Synfronia</div>\n        <div id="ffmpeg-sub" data-i18n="ffmpeg.overlay_hint">Для слияния видео и аудио, субтитров, метаданных и перекодировки нужен ffmpeg.</div>\n      </div>\n      <div style="position:relative;display:inline-block">\n        <button type="button" id="ffmpeg-dl">\n          <span data-i18n="ffmpeg.download">Загрузить FFmpeg</span>\n          <canvas width="640" height="148"></canvas>\n        </button>\n        <div id="ffmpeg-progress" class="ffmpeg-hidden">\n          <svg id="ffmpeg-ring" viewBox="0 0 120 120">\n            <circle class="ring-bg" cx="60" cy="60" r="52"></circle>\n            <circle class="ring-fg" cx="60" cy="60" r="52"></circle>\n          </svg>\n          <div id="ffmpeg-percent">0%</div>\n        </div>\n      </div>\n      <div id="ffmpeg-status"></div>\n      <button type="button" id="ffmpeg-retry" data-i18n="ffmpeg.download">Загрузить FFmpeg</button>\n    </div>\n  </div>\n<!-- /SLOT:ffmpeg-overlay -->\n\n\n  \n<!-- SLOT:actions -->\n<div class="actions">\n    <button id="download" class="dl" type="button">\n      <span class="dl-fill"></span>\n      <span class="dl-label" data-i18n="btn.download">Скачать</span>\n      <span class="dl-pct"></span>\n      <span class="dl-icon" aria-hidden="true"></span>\n    </button>\n    <button id="stop" disabled data-i18n="btn.stop">Отмена</button>\n  </div>\n<!-- /SLOT:actions -->\n\n\n  \n<!-- SLOT:progress -->\n<div class="pb-wrap"><div id="pb"></div></div>\n  <div id="status">Готов.</div>\n  <textarea id="log" readonly></textarea>\n<!-- /SLOT:progress -->\n\n  \n<!-- SLOT:clicker -->\n<div class="clicker-row">\n    <div id="clicker-msg" class="clicker-msg"></div>\n    <button type="button" id="clicker" class="clicker" data-i18n-title="clicker.title" title="…">Кликни меня~</button>\n  </div>\n<!-- /SLOT:clicker -->\n\n\n  \n<!-- SLOT:modal -->\n<div id="settings-block" class="overlay" hidden></div>\n<!-- /SLOT:modal -->\n\n\n  \n<script>__COMMONJS__</script>\n<script>__APPJS__</script>\n</body>\n</html>\n'

